import json
from kafka import KafkaConsumer
from neo4j import GraphDatabase

# 1. Connect to Neo4j Graph Database
NEO4J_URI = "bolt://localhost:7687"
NEO4J_USER = "neo4j"
NEO4J_PASSWORD = "AetherisSecretPassword123"

print("[*] Connecting to Neo4j...")
neo4j_driver = GraphDatabase.driver(NEO4J_URI, auth=(NEO4J_USER, NEO4J_PASSWORD))

# 2. Connect to Redpanda (Kafka) Consumer
print("[*] Connecting to Redpanda Stream...")
consumer = KafkaConsumer(
    'raw-osint',
    bootstrap_servers=['localhost:19092'],
    auto_offset_reset='earliest', # Reads from beginning to catch previous test messages
    enable_auto_commit=True,
    value_deserializer=lambda m: json.loads(m.decode('utf-8'))
)

# 3. Cypher Query: Map the intelligence event to graph nodes and edges
def map_event_to_graph(tx, event_data):
    query = """
    MERGE (source:IntelSource {source_id: $source_id})
    MERGE (sector:Sector {name: $location_hint})
    
    // Create an IntelEvent node and link relationships
    CREATE (event:IntelEvent {
        timestamp: $timestamp, 
        raw_text: $raw_text, 
        classification: $classification
    })
    
    CREATE (source)-[:REPORTED]->(event)
    CREATE (event)-[:OCCURRED_IN]->(sector)
    """
    
    tx.run(query, 
           source_id=event_data.get('source_id'),
           location_hint=event_data.get('location_hint'),
           timestamp=event_data.get('timestamp'),
           raw_text=event_data.get('raw_text'),
           classification=event_data.get('classification'))

# 4. Processing Loop
print("[+] AI Worker Active. Waiting for OSINT events...")

try:
    for message in consumer:
        payload = message.value
        print(f"\n[Incoming Event] Source: {payload.get('source_id')}")
        print(f"Text: {payload.get('raw_text')}")
        
        # Write to Neo4j
        with neo4j_driver.session() as session:
            session.execute_write(map_event_to_graph, payload)
            
        print("[Graph DB] Nodes and Edges committed successfully.")
        
except KeyboardInterrupt:
    print("\n[-] Shutting down AI worker.")
finally:
    neo4j_driver.close()
    consumer.close()